@Injectable()
export class PlaceOrderService {
  constructor(
    private readonly prisma: PrismaService,
    private readonly customers: CustomerRepository,
    private readonly orders: OrderRepository,
  ) {}

  async place(cmd: PlaceOrderCommand): Promise<OrderId> {
    return this.prisma.$transaction(async (tx) => {   // commit on return, rollback on throw
      const customer = await this.customers.ofId(tx, cmd.customerId);
      const order = customer.placeOrder(cmd.items);   // the aggregate decides
      await this.orders.add(tx, order);
      return order.id;
    });
  }
}

