export async function placeOrder(
  cmd: PlaceOrderCommand,
  deps: { prisma: PrismaClient; orders: OrderRepository; customers: CustomerRepository },
): Promise<OrderId> {
  return deps.prisma.$transaction(async (tx) => {
    const customer = await deps.customers.ofId(tx, cmd.customerId);
    const order = customer.placeOrder(cmd.items);   // the aggregate decides
    await deps.orders.add(tx, order);
    return order.id;
  });
}
